SELECT d.*, c.name AS detailName, c.normal_value AS normalValue, c.unit FROM report_item_detail d LEFT JOIN checkitem_detail c ON d.detail_id = c.id
AND d.report_id = #{reportId}
AND d.is_abnormal = #{isAbnormal}
ORDER BY d.id

